// Valida payload UAZAPI e extrai dados (texto ou audio).
const THIAGO_NUMEROS = ['5511964486564', '5511910441709'];

const body = items[0].json.body || items[0].json;
const msg = body.message || body.data || body;

// Ignorar fromMe
const fromMe = msg.fromMe === true || msg.key?.fromMe === true;
if (fromMe) return [];

// Ignorar grupos
const chatId = String(msg.chatid || msg.chatId || msg.key?.remoteJid || '');
if (chatId.includes('@g.us') || chatId.includes('-')) return [];

const senderNumero = chatId.replace(/@.*$/, '').replace(/[^0-9]/g, '');
if (!senderNumero || senderNumero.length < 10) return [];

// Timestamp Brasilia (UTC-3)
const agora = new Date(Date.now() - (3 * 60 * 60 * 1000));
const agoraISO = agora.toISOString().replace('T', ' ').substring(0, 19);
const ehThiago = THIAGO_NUMEROS.includes(senderNumero);
const messageId = msg.id || msg.messageid || msg.key?.id || '';

// Detectar audio (varios formatos UAZAPI/WA possiveis)
const messageType = String(msg.messageType || msg.type || msg.mediaType || '').toLowerCase();
const audioPayload = msg.audioMessage || msg.audio || msg.message?.audioMessage || null;
const isAudio = ['audio','audiomessage','voice','voicemessage','ptt'].includes(messageType) || !!audioPayload;

const base = {
  valido: true,
  eh_thiago: ehThiago,
  sender_numero: senderNumero,
  sender_nome_push: msg.pushName || msg.notifyName || '',
  timestamp_agora_brasilia: agoraISO,
  message_id: messageId,
  tem_audio: isAudio,
  audio_id: isAudio ? messageId : '',
  audio_mime: isAudio ? (msg.mimetype || audioPayload?.mimetype || 'audio/ogg') : '',
  audio_base64: ''
};

if (isAudio) {
  return [{ json: { ...base, texto: '' } }];
}

// Extrair texto
const texto = msg.text || msg.body || msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.content || '';
let textoFinal = '';
if (typeof texto === 'string') textoFinal = texto;
else if (texto && typeof texto === 'object') textoFinal = '[mensagem nao-textual]';
else textoFinal = String(texto || '');
if (!textoFinal.trim() || textoFinal === '[object Object]') {
  textoFinal = '[mensagem nao-textual]';
}

// Detectar mensagens automaticas (auto-resposta, horario comercial, ausencia,
// encerramento de atendimento, lembrete de cliente, marketing)
// Pra essas, NAO responder - evita loop com outros bots
const t = textoFinal.toLowerCase();
const isAutoReply = !ehThiago && (
  // 1. Mensagens de fora-de-expediente / disponibilidade
  /n[aã]o estamos dispon[ií]veis/i.test(t) ||
  /hor[aá]rio de atendimento/i.test(t) ||
  /retornaremos.{0,30}(em breve|assim que poss[ií]vel)/i.test(t) ||
  /resposta autom[aá]tica/i.test(t) ||
  /fora do (expediente|hor[aá]rio)/i.test(t) ||
  /deixe (sua mensagem|seu recado).{0,40}retorna/i.test(t) ||
  /aguarde.{0,30}retornar?emos/i.test(t) ||
  // 2. Encerramento automatico de atendimento
  /\*?\s*atendimento\s+encerrado/i.test(t) ||
  /vou encerrar (nosso |o |seu )?atendimento/i.test(t) ||
  /encerrar.{0,30}por falta de intera[cç][aã]o/i.test(t) ||
  /n[aã]o precisa responder essa mensagem/i.test(t) ||
  /(esse|este) atendimento foi encerrado/i.test(t) ||
  // 3. Mensagens de retomada / follow-up automatico
  /notei que ainda n[aã]o tivemos retorno/i.test(t) ||
  /assim que (voc[eê] )?responder.{0,30}seguimos/i.test(t) ||
  /(fizemos )?uma tentativa de contato/i.test(t) ||
  // 4. Marketing / saudade / promocao
  /(bateu )?saudade.{0,30}(de voc[eê]|por aqui)/i.test(t) ||
  /cliente especial.{0,40}(merece|separou)/i.test(t) ||
  /toque no link/i.test(t) ||
  /clique no link.{0,30}(abaixo|para)/i.test(t) ||
  /n[aã]o some sem fazer falta/i.test(t) ||
  /sua (pr[oó]xima )?visita/i.test(t) ||
  // 5. Confirmacao/agradecimento automatico
  /obrigado pelo contato.{0,40}(salve nosso n[uú]mero|fico a disposi[cç][aã]o)/i.test(t) ||
  /salve nosso n[uú]mero (na sua agenda|nos contatos)/i.test(t)
);
if (isAutoReply) {
  // Retorna vazio - Pipeline nao processa, Giulia nao responde
  return [];
}

return [{ json: { ...base, texto: textoFinal.trim() } }];

// Le o texto transcrito do Whisper e injeta como 'texto' do msgAtual
// Pipeline subsequente trata como mensagem de texto normal
const prev = $('Validar Mensagem').first().json;
const whisperResp = $input.first().json || {};

const transcricao = (whisperResp.text || '').trim();

return [{
  json: {
    ...prev,
    texto: transcricao,
    tem_audio: false,
    audio_transcrito: true,
    audio_transcricao: transcricao
  }
}];

// Parseia resposta Gemini e monta SQL/HTTP da acao escolhida
const prev = $('Montar Prompt').first().json;
const geminiResp = items[0].json;

let rawText = '';
try { rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || ''; } catch(e) {}

function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) { return null; }
}

let dec = parseJson(rawText);
if (!dec) {
  // Parse falhou - tentar extrair so o campo resposta via regex (fallback)
  let respFallback = '';
  try {
    const m = rawText.match(/"resposta"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    if (m) respFallback = m[1].replace(/\\"/g,'"').replace(/\\n/g,' ').trim();
  } catch(e) {}
  // Se conseguiu pegar resposta natural via regex, usa. Senao, deixa simples.
  dec = { acao: 'apenas_responder', parametros: {}, resposta: respFallback || 'Pode mandar de novo? Nao consegui te ouvir direito.' };
}
let acao = dec.acao || 'apenas_responder';
const p = dec.parametros || {};

// Fallback defensivo: se Gemini escolheu agendar_mensagem/enviar_agora pra
// um numero do Thiago, isso na verdade eh um lembrete (ele falou consigo mesmo).
const THIAGO_NUMEROS_FB = ['5511964486564', '5511910441709'];
const destNum = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
if (['agendar_mensagem','enviar_agora'].includes(acao) && THIAGO_NUMEROS_FB.includes(destNum)) {
  if (acao === 'agendar_mensagem') {
    acao = 'criar_lembrete';
    p.descricao = p.descricao || p.texto || p.conteudo || prev.texto_original || 'lembrete';
  } else {
    acao = 'apenas_responder';
    dec.resposta = 'Pra voce mesmo seria um lembrete imediato? Manda assim: "me lembra daqui X minutos de Y".';
  }
}
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const escOrNull = s => (s == null || s === '') ? 'NULL' : `'${esc(s)}'`;

// Texto original: se foi audio usa transcricao, senao usa o texto que veio
const textoSalvarMemoria = prev.tem_audio
  ? (dec.transcricao_audio || '[audio sem transcricao]')
  : (prev.texto_original || '');

let acao_tipo = 'REPLY_ONLY';
let sql_query = '';
let send_to_number = '';
let send_text = '';
let envio_pendente_id = null;

// Facts novos pra salvar (extraidos pelo Gemini)
const factsNovos = Array.isArray(dec.facts_novos) ? dec.facts_novos.filter(f => f && f.fact) : [];

const senderNumero = prev.sender_numero;
const senderNomePush = prev.sender_nome_push || '';

if (prev.eh_thiago) {
  // Validacao defensiva: se Gemini escolheu enviar mas o numero veio vazio/invalido,
  // degrada pra apenas_responder ao inves de quebrar com 'Missing required fields'.
  if (['agendar_mensagem','enviar_agora'].includes(acao)) {
    const numLimpo = String(p.destinatario_numero || '').replace(/[^0-9]/g, '');
    if (numLimpo.length < 10) {
      acao = 'apenas_responder';
      dec.resposta = 'Nao identifiquei o numero do destinatario. Me passa o numero (55DDNNNNNNNNN) ou o nome exato dos contatos conhecidos.';
    }
  }
  if (acao === 'salvar_ideia') {
    acao_tipo = 'DB_OP';
    const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
    const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
    sql_query = `INSERT INTO giulia_ideias (conteudo, tags) VALUES ('${esc(p.conteudo)}', ${tagsSql}) RETURNING id, conteudo;`;
  } else if (acao === 'salvar_contato') {
    const numContato = String(p.destinatario_numero || p.numero || '').replace(/[^0-9]/g, '');
    if (!numContato || numContato.length < 10) {
      acao = 'apenas_responder';
      dec.resposta = 'Pra salvar o contato preciso do numero (55DDNNNNNNNNN). Me manda o numero junto com o nome.';
    } else {
      acao_tipo = 'DB_OP';
      const apelidosArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : (Array.isArray(p.apelidos) ? p.apelidos.filter(Boolean) : []);
      const apelidosSql = apelidosArr.length ? `ARRAY[${apelidosArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
      const nome = p.destinatario_nome || p.nome || ('Contato ' + numContato);
      sql_query = `INSERT INTO giulia_contatos (nome, apelidos, numero, observacoes) VALUES ('${esc(nome)}', ${apelidosSql}, '${esc(numContato)}', ${escOrNull(p.observacoes)}) ON CONFLICT (numero) DO UPDATE SET nome = COALESCE(EXCLUDED.nome, giulia_contatos.nome), apelidos = COALESCE(EXCLUDED.apelidos, giulia_contatos.apelidos), observacoes = COALESCE(EXCLUDED.observacoes, giulia_contatos.observacoes) RETURNING id, nome, numero;`;
    }
  } else if (acao === 'criar_lembrete') {
    acao_tipo = 'DB_OP';
    const rec = p.recorrencia ? `'${esc(p.recorrencia)}'` : 'NULL';
    const desc = p.descricao || prev.texto_original || 'lembrete';
    sql_query = `INSERT INTO giulia_lembretes (descricao, disparar_em, recorrencia) VALUES ('${esc(desc)}', '${esc(p.disparar_em)}'::TIMESTAMP, ${rec}) RETURNING id, descricao, disparar_em;`;
  } else if (acao === 'agendar_mensagem') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para) VALUES ('${esc(p.destinatario_numero)}', '${esc(p.destinatario_nome)}', '${esc(p.texto)}', '${esc(p.disparar_em || p.agendado_para)}'::TIMESTAMP) RETURNING id, destinatario_nome, agendado_para;`;
  } else if (acao === 'enviar_agora') {
    acao_tipo = 'SEND_NOW';
    send_to_number = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
    send_text = String(p.texto || '');
  } else if (acao === 'enviar_com_confirmacao') {
    const numLimpo = String(p.destinatario_numero || '').replace(/[^0-9]/g, '');
    if (numLimpo.length < 10 || !p.texto) {
      acao = 'apenas_responder';
      dec.resposta = 'Faltou numero ou texto do envio. Como queres mandar?';
    } else {
      acao_tipo = 'DB_OP';
      sql_query = `INSERT INTO giulia_envios_pendentes (destinatario_numero, destinatario_nome, texto) VALUES ('${esc(numLimpo)}', ${escOrNull(p.destinatario_nome)}, '${esc(p.texto)}') RETURNING id;`;
    }
  } else if (acao === 'confirmar_envio') {
    // Busca o pendente nos envios carregados
    try {
      const pend = $('Carregar Envios Pendentes').all().map(i => i.json).filter(x => x && x.id);
      let chosen = null;
      if (p.id_envio) chosen = pend.find(x => String(x.id) === String(p.id_envio));
      if (!chosen && pend.length === 1) chosen = pend[0];
      if (chosen) {
        acao_tipo = 'SEND_NOW';
        send_to_number = String(chosen.destinatario_numero).replace(/[^0-9]/g,'');
        send_text = chosen.texto;
        envio_pendente_id = chosen.id;
      } else {
        acao = 'apenas_responder';
        dec.resposta = 'Nao achei o envio pendente. Qual id?';
      }
    } catch(e) {
      acao = 'apenas_responder';
      dec.resposta = 'Tive problema buscando o envio pendente.';
    }
  } else if (acao === 'cancelar_envio') {
    if (p.id_envio) {
      acao_tipo = 'DB_OP';
      sql_query = `UPDATE giulia_envios_pendentes SET status = 'cancelado' WHERE id = ${parseInt(p.id_envio,10)} AND status = 'aguardando_confirmacao' RETURNING id;`;
    } else {
      acao = 'apenas_responder';
      dec.resposta = 'Qual id pra cancelar?';
    }
  } else if (acao === 'listar_ideias') {
    acao_tipo = 'DB_OP';
    const tag = p.filtro_tag ? esc(p.filtro_tag) : null;
    sql_query = tag
      ? `SELECT id, conteudo, tags, created_at FROM giulia_ideias WHERE '${tag}' = ANY(tags) ORDER BY created_at DESC LIMIT 20;`
      : `SELECT id, conteudo, tags, created_at FROM giulia_ideias ORDER BY created_at DESC LIMIT 20;`;
  } else if (acao === 'listar_lembretes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, descricao, disparar_em, recorrencia, status FROM giulia_lembretes WHERE status = 'pendente' ORDER BY disparar_em ASC LIMIT 20;`;
  } else if (acao === 'listar_leads') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome, numero, tipo_projeto, porte, localizacao, fase, resumo, status, criado_em FROM giulia_leads WHERE status IN ('novo','em_atendimento','agendado') ORDER BY criado_em DESC LIMIT 20;`;
  } else if (acao === 'listar_reunioes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome_cliente, numero_cliente, agendado_para, assunto, status FROM giulia_reunioes WHERE status IN ('pendente_aprovacao_thiago','agendada','confirmada') ORDER BY agendado_para ASC LIMIT 20;`;
  } else if (acao === 'listar_notificacoes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, tipo, origem_nome, origem_numero, resumo, urgencia, criada_em FROM giulia_notificacoes_thiago WHERE status = 'pendente' ORDER BY criada_em DESC LIMIT 20;`;
  } else if (acao === 'aprovar_reuniao' && p.id_reuniao) {
    acao_tipo = 'DB_OP';
    // Aprova + agenda confirmacao automatica pro CLIENTE (scheduler envia em ate 1 min)
    sql_query = `WITH r AS (
  UPDATE giulia_reunioes SET status = 'agendada', confirmada_em = NOW()
  WHERE id = ${parseInt(p.id_reuniao,10)} AND status = 'pendente_aprovacao_thiago'
  RETURNING id, nome_cliente, numero_cliente, agendado_para, assunto
)
INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para)
SELECT numero_cliente, nome_cliente,
  'Oi' || CASE WHEN nome_cliente IS NOT NULL AND nome_cliente != '' THEN ' ' || split_part(nome_cliente,' ',1) ELSE '' END || ', tudo bem? O Thiago confirmou a conversa de voces' ||
  CASE WHEN agendado_para IS NOT NULL THEN ' para ' || to_char(agendado_para,'DD/MM') || ' as ' || to_char(agendado_para,'HH24:MI') ELSE '' END ||
  '. Qualquer imprevisto me avisa por aqui. Ate la!',
  NOW() AT TIME ZONE 'America/Sao_Paulo'
FROM r
RETURNING id;`;
  } else if (acao === 'salvar_rotina') {
    const lista = Array.isArray(p.rotinas_lista) ? p.rotinas_lista.filter(r => r && r.tarefa && r.dia_semana !== undefined) : [];
    if (!lista.length) {
      acao = 'apenas_responder';
      dec.resposta = 'Nao consegui extrair as tarefas. Manda no formato "segunda: jogar lixo, terca: dar banho".';
    } else {
      acao_tipo = 'DB_OP';
      const aviso = p.hora_aviso && /^\d{1,2}:\d{2}$/.test(p.hora_aviso) ? p.hora_aviso : '07:00';
      const reforco = p.hora_reforco && /^\d{1,2}:\d{2}$/.test(p.hora_reforco) ? p.hora_reforco : '12:00';
      const values = lista.map(r => `(${parseInt(r.dia_semana,10)}, '${esc(r.tarefa)}', '${esc(aviso)}'::TIME, '${esc(reforco)}'::TIME)`).join(', ');
      sql_query = `INSERT INTO giulia_rotina (dia_semana, tarefa, hora_aviso, hora_reforco) VALUES ${values} ON CONFLICT (dia_semana, tarefa) DO UPDATE SET hora_aviso = EXCLUDED.hora_aviso, hora_reforco = EXCLUDED.hora_reforco, ativa = TRUE RETURNING id, dia_semana, tarefa;`;
    }
  } else if (acao === 'listar_rotina') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, dia_semana, tarefa, hora_aviso, hora_reforco FROM giulia_rotina WHERE ativa = TRUE ORDER BY dia_semana, id;`;
  } else if (acao === 'deletar_rotina' && p.id_rotina) {
    acao_tipo = 'DB_OP';
    sql_query = `UPDATE giulia_rotina SET ativa = FALSE WHERE id = ${parseInt(p.id_rotina,10)} RETURNING id, tarefa;`;
  } else if (acao === 'salvar_tarefa') {
    const titulo = p.titulo || p.descricao || p.conteudo || prev.texto_original;
    if (!titulo) {
      acao = 'apenas_responder';
      dec.resposta = 'O que voce quer salvar como tarefa?';
    } else {
      acao_tipo = 'DB_OP';
      const prazo = p.prazo && /^\d{4}-\d{2}-\d{2}/.test(p.prazo) ? `'${esc(p.prazo.substring(0,10))}'::DATE` : 'NULL';
      // proxima cobranca: hoje as 18h Brasilia se tem prazo hoje, senao amanha 9h
      const desc = p.descricao && p.descricao !== titulo ? `'${esc(p.descricao)}'` : 'NULL';
      sql_query = `INSERT INTO giulia_tarefas (titulo, descricao, prazo, proxima_cobranca_em) VALUES ('${esc(titulo)}', ${desc}, ${prazo}, NOW() + INTERVAL '4 hours') RETURNING id, titulo, prazo;`;
    }
  } else if (acao === 'listar_tarefas') {
    acao_tipo = 'DB_OP';
    const where = ["status = 'pendente'"];
    if (p.filtro_periodo === 'hoje') where.push("(prazo IS NULL OR prazo = CURRENT_DATE)");
    if (p.filtro_periodo === 'semana') where.push("(prazo IS NULL OR prazo <= CURRENT_DATE + INTERVAL '7 days')");
    if (p.filtro_periodo === 'atrasadas') where.push("prazo < CURRENT_DATE");
    sql_query = `SELECT id, titulo, descricao, prazo, criada_em, cobranca_count FROM giulia_tarefas WHERE ${where.join(' AND ')} ORDER BY (prazo IS NULL), prazo ASC, criada_em ASC LIMIT 30;`;
  } else if (acao === 'marcar_tarefa_feita' && p.id_tarefa) {
    acao_tipo = 'DB_OP';
    sql_query = `UPDATE giulia_tarefas SET status = 'feita', feita_em = NOW() WHERE id = ${parseInt(p.id_tarefa,10)} AND status = 'pendente' RETURNING id, titulo;`;
  } else if (acao === 'cancelar_tarefa' && p.id_tarefa) {
    acao_tipo = 'DB_OP';
    sql_query = `UPDATE giulia_tarefas SET status = 'cancelada' WHERE id = ${parseInt(p.id_tarefa,10)} AND status = 'pendente' RETURNING id, titulo;`;
  } else if (acao === 'adiar_tarefa' && p.id_tarefa) {
    acao_tipo = 'DB_OP';
    const np = p.novo_prazo && /^\d{4}-\d{2}-\d{2}/.test(p.novo_prazo) ? `'${esc(p.novo_prazo.substring(0,10))}'::DATE` : 'NULL';
    sql_query = `UPDATE giulia_tarefas SET prazo = ${np}, proxima_cobranca_em = NOW() + INTERVAL '20 hours' WHERE id = ${parseInt(p.id_tarefa,10)} AND status = 'pendente' RETURNING id, titulo, prazo;`;
  } else if (acao === 'registrar_gasto') {
    acao_tipo = 'DB_OP';
    const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
    const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
    const valor = parseFloat(p.valor) || 0;
    const dataGasto = p.data_gasto && p.data_gasto.length >= 10 ? `'${esc(p.data_gasto.substring(0,10))}'::DATE` : 'CURRENT_DATE';
    sql_query = `INSERT INTO giulia_gastos (descricao, valor, categoria, forma_pagamento, tags, data_gasto, observacoes) VALUES ('${esc(p.descricao || p.conteudo)}', ${valor}, ${escOrNull(p.categoria)}, ${escOrNull(p.forma_pagamento)}, ${tagsSql}, ${dataGasto}, ${escOrNull(p.observacoes)}) RETURNING id, descricao, valor, categoria;`;
  } else if (acao === 'listar_gastos') {
    acao_tipo = 'DB_OP';
    const where = [];
    if (p.filtro_categoria) where.push(`categoria = '${esc(p.filtro_categoria)}'`);
    if (p.valor_min) where.push(`valor >= ${parseFloat(p.valor_min)}`);
    if (p.valor_max) where.push(`valor <= ${parseFloat(p.valor_max)}`);
    const periodoMap = { hoje: "data_gasto = CURRENT_DATE", semana: "data_gasto >= CURRENT_DATE - INTERVAL '7 days'", mes: "data_gasto >= date_trunc('month', CURRENT_DATE)", '30dias': "data_gasto >= CURRENT_DATE - INTERVAL '30 days'", ano: "data_gasto >= date_trunc('year', CURRENT_DATE)" };
    if (p.filtro_periodo && periodoMap[p.filtro_periodo]) where.push(periodoMap[p.filtro_periodo]);
    const whereSql = where.length ? 'WHERE ' + where.join(' AND ') : '';
    sql_query = `SELECT id, descricao, valor, categoria, forma_pagamento, data_gasto FROM giulia_gastos ${whereSql} ORDER BY data_gasto DESC, id DESC LIMIT 30;`;
  } else if (acao === 'resumo_gastos') {
    acao_tipo = 'DB_OP';
